PROCEDURE    WP_RP_CR_OKUL_ODEME_KONTROL_S ( pkurum           IN NUMBER,
iogrencino       IN VARCHAR2,
iTCKN            IN VARCHAR2,
dbastar          IN VARCHAR2,
dbittar          IN VARCHAR2,
iokulodemeplanno IN NUMBER,
pdrm             IN NUMBER DEFAULT 0) IS
-- MODIFICATION HISTORY
-- Person               Date            Comments
-- ---------------      -----------     -------------------------------------------
-- Halime GENÇ          28/07/2015      Created
-- Halime GENÇ          28/07/2015      Okul Tahsilatlari
-- Sinem AKIN           12/07/2016      Sube, hesap no ve hesap mus_ad bilgisi eklendi.
-- Halime GENÇ          11/08/2016      Ilktaksittar eklendi.
-- Mehmet Atesçi        18/09/2017      Hata Ack
-----------------------------------------------------------------------------------
wBastar                DATE;
wBittar                DATE;
wTur                   number;
wFAT_HATA_ACK           VARCHAR2(3000);
wrenk                  VARCHAR2(3000);
wPesinatTahsilDrm      VARCHAR2(100);
wKurumCalismaTipi      NUMBER;
wPlanBildirilmeDurumu  VARCHAR2(100);
whesmusteriadi         VARCHAR2(100):= NULL;
CURSOR cur_okulodemeplan IS
SELECT okulodemeplanno,
fatkurumno,
 ogrencino,
borcno,
borcack,
tckn,
adsoyad,
fakulte,
bolum,
drm,
odemetipi,
decode(drm,1,'Geçerli',2,'Geçerli',9,'Iptal','-') durum,
decode(odemetipi,'P','Pesin','V','Vadeli','-') odemesekli,
decode(odemetipi,'P',pesin_tut,'V',vadeli_tut,'-') toplamtutar,
pesinat_tut,
fatodemeno,
taksitsayisi,
decode(kmh_drm,1,'Talep Bulunamadi',2,'Basarili',9,'Basarisiz','-') kmh_drm,
kmh_limit,
plan_bld_tar,
tarih, sube, hesno, ilktaksittar,
hata_ack
FROM okul_odeme_plan
WHERE (pkurum = 0 OR fatkurumno = pkurum)
AND (iogrencino IS NULL OR ogrencino = trim(iogrencino))
AND (iTCKN IS NULL OR TCKN = trim(iTCKN))
AND (iokulodemeplanno IS NULL OR okulodemeplanno = iokulodemeplanno)
AND (wBastar IS NULL OR tarih>=wBastar)
AND (wBittar IS NULL OR tarih<=wBittar)
AND (pdrm = 0 OR ((pdrm=9 AND drm=pdrm) OR (pdrm=1 AND drm IN (1,2))))
ORDER BY 1 DESC;
CURSOR cur_kurum (pFatkurumno IN NUMBER) IS
SELECT ref_fat_sorgu_tur
FROM fat_kurum
WHERE fatkurumno = pFatkurumno;
BEGIN
P_Set_Ortam_web;
web_ortak.p_baslik('Okul Tahsilatlari Gözlem');
IF iokulodemeplanno IS null AND pkurum = 0 THEN
web_ortak.p_hata('Okul Tahsilatlari Gözlem','Lütfen Kurum Bilgisi veya TEB Kayit No Bilgisini Doldurunuz.','WP_RP_CR_SAY2000_ODM_KONTROL_G');
ELSIF (dbastar IS NOT NULL AND  F_TARIH_KONT(dbastar, 'DDMMRR') = 0 ) OR
(dbittar IS NOT NULL AND  F_TARIH_KONT(dbittar, 'DDMMRR') = 0 ) THEN
web_ortak.p_hata('Okul Tahsilatlari Gözlem','Lütfen Tarih Araligi Bilgisini Dogru Formatta Doldurunuz.','WP_RP_CR_OKUL_ODEME_KONTROL_G');
ELSIF to_date(dbittar,'DDMMRR') < to_date(dbastar,'DDMMRR')  THEN
web_ortak.p_hata('Okul Tahsilatlari Gözlem','Baslangiç Tarihi Bitis Tarihinden Büyük Olamaz.','WP_RP_CR_OKUL_ODEME_KONTROL_G');
ELSIF iokulodemeplanno IS NOT NULL AND f_number_kont(iokulodemeplanno) = 0 THEN
web_ortak.p_hata('Okul Tahsilatlari Gözlem','Lütfen Teb Kayit No Bilgisini Dogru Formatta Doldurunuz.','WP_RP_CR_OKUL_ODEME_KONTROL_G');
ELSE
wBastar := to_date(dbastar,'DDMMRR');
wBittar := to_date(dbittar,'DDMMRR');
htp.p('<br>');
-- Seçilen Kriterler -------------
web_ortak.p_form_tablo_ac;
htp.p('<tr>'||web_ortak.f_hucre('Kurum',F_KURUM_ADI(pkurum,'A')));
htp.p('<tr>'||web_ortak.f_hucre('Ögrenci No',iogrencino));
htp.p('<tr>'||web_ortak.f_hucre('Tarih Araligi',to_char(wBastar,'dd/mm/rrrr') ||' - '||to_char(wBittar,'dd/mm/rrrr')));
htp.p('<tr>'||web_ortak.f_hucre('TEB Kayit No',iokulodemeplanno));
web_ortak.p_tablo_kapa;
-----------------------------------
htp.p('<br>');
web_ortak.p_tablo_ac('TEB Kayit No'          ||chr(6)||
'Kurum'                 ||chr(6)||
'Ögrenci No'            ||chr(6)||
'Borç No'               ||chr(6)||
'Borç Ack'              ||chr(6)||
'TCKN'                  ||chr(6)||
'Ad Soyad'              ||chr(6)||
'Fakülte'               ||chr(6)||
'Bölüm'                 ||chr(6)||
'Plan Olusturulma Tarihi'  ||chr(6)||
'Plan Durumu'           ||chr(6)||
'Ödeme Sekli'           ||chr(6)||
'Toplam Tutar'          ||chr(6)||
'Pesinat'               ||chr(6)||
'Pesinat Tahsil Durumu' ||chr(6)||
'Taksit Sayisi'         ||chr(6)||
'Taksit Baslangiç Tarihi'||chr(6)||
'KMH Durumu'            ||chr(6)||
'KMH Tutari'            ||chr(6)||
'Veli Sube'             ||chr(6)||
'Veli Hesap No'         ||chr(6)||
'Veli Ad Soyad'         ||chr(6)||
'Plan Bildirilme Durumu'||chr(6)||
'Ödeme Hata Açiklama'   ||chr(6)||
'   '
);
FOR r IN cur_okulodemeplan
LOOP
wPesinatTahsilDrm := NULL;
IF  r.pesinat_tut = 0 THEN
wPesinatTahsilDrm := '-' ;
ELSE
IF r.fatodemeno IS NULL THEN
wPesinatTahsilDrm := 'Tahsil edilmedi';
ELSE
wPesinatTahsilDrm := 'Tahsil edildi';
END IF;
END IF;
wKurumCalismaTipi := NULL;
OPEN  cur_kurum(r.fatkurumno);
FETCH cur_kurum INTO wKurumCalismaTipi;
CLOSE cur_kurum;
wPlanBildirilmeDurumu := NULL;
IF wKurumCalismaTipi = 2 THEN  -- OFFLINE
IF r.plan_bld_tar IS NOT NULL THEN
wPlanBildirilmeDurumu := 'Okula Bildirildi';
ELSE
wPlanBildirilmeDurumu := 'Okula Bildirilmedi';
END IF;
ELSE -- online
IF r.drm=2 THEN
wPlanBildirilmeDurumu := 'Okula Bildirildi';
ELSE
wPlanBildirilmeDurumu := 'Okula Bildirilmedi';
END IF;
END IF;
whesmusteriadi := NULL;
IF r.sube IS NOT NULL AND r.hesno IS NOT NULL THEN
whesmusteriadi := f_hesap_musteri_adi_genel(r.hesno,r.sube);
END IF;
--MehmetAtesçi
if r.hata_ack is null then
begin
select f_dberrorformatla(tahbldhataack) into wFAT_HATA_ACK from tb.fat_odeme where fatkurumno=r.fatkurumno and trim(kurum_kyt_no)=r.ogrencino and faturano=r.borcno;
exception when others then
wFAT_HATA_ACK:=null;
end;
else
wFAT_HATA_ACK:=r.hata_ack;
end if;
--
htp.p('<tr>'||'<td align=center><p>' || r.okulodemeplanno ||'&nbsp'||'</td>'||
'<td align=left><p>'   || r.fatkurumno || ' - ' ||F_KURUM_ADI(r.fatkurumno,'A') ||'&nbsp'||'</td>'||
'<td align=center><p>' || r.ogrencino ||'&nbsp'||'</td>'||
'<td align=left><p>'   || r.borcno ||'&nbsp'||'</td>'||
'<td align=left><p>'   || r.borcack ||'&nbsp'||'</td>'||
'<td align=center><p>' || r.tckn ||'&nbsp'||'</td>'||
'<td align=left><p>'   || r.adsoyad ||'&nbsp'||'</td>'||
'<td align=left><p>'   || r.fakulte ||'&nbsp'||'</td>'||
'<td align=left><p>'   || r.bolum ||'&nbsp'||'</td>'||
'<td align=center><p>' || r.tarih ||'&nbsp'||'</td>'||
'<td align=center><p>' || r.durum ||'&nbsp'||'</td>'||
'<td align=center><p>' || r.odemesekli ||'&nbsp'||'</td>'||
'<td align=right><p>'  || F_TUTAR_FORMATLA('TL',r.toplamtutar) ||'&nbsp'||'</td>'||
'<td align=right><p>'  || F_TUTAR_FORMATLA('TL',r.pesinat_tut) ||'&nbsp'||'</td>'||
'<td align=center><p>' || wPesinatTahsilDrm ||'&nbsp'||'</td>'||
'<td align=right><p>'  || r.taksitsayisi ||'&nbsp'||'</td>'||
'<td align=center><p>'  || r.ilktaksittar ||'&nbsp'||'</td>'||
'<td align=center><p>' || r.kmh_drm ||'&nbsp'||'</td>'||
'<td align=right><p>'  || F_TUTAR_FORMATLA('TL',r.kmh_limit) ||'&nbsp'||'</td>'||
'<td align=center><p>'  || r.sube ||'&nbsp'||'</td>'||
'<td align=center><p>'  || r.hesno ||'&nbsp'||'</td>'||
'<td align=left><p>'  || whesmusteriadi ||'&nbsp'||'</td>'||
'<td align=center><p>' || wPlanBildirilmeDurumu ||'&nbsp'||'</td>'||
'<td align=center><p>' || wFAT_HATA_ACK ||'&nbsp'||'</td>');
htp.p('<td align=center><p>'  || web_ortak.f_link('WP_RP_CR_OKUL_ODEME_KONTROL_D?pokulodemeplanno='      ||r.okulodemeplanno, 'Detaylar için tiklayiniz.') ||'&nbsp'||'</td>');
END LOOP;
web_ortak.p_tablo_kapa;
web_ortak.p_kapanis;
END IF;
EXCEPTION
WHEN OTHERS THEN
web_ortak.p_sql_hata;
END;

