/**
 * CURSOR cur_okulodemeplan IS
 *   SELECT okulodemeplanno,
 *          fatkurumno,
 *          ogrencino,
 *          borcno,
 *          borcack,
 *          tckn,
 *          adsoyad,
 *          fakulte,
 *          bolum,
 *          drm,
 *          odemetipi,
 *          decode(drm,1,'Geçerli',2,'Geçerli',9,'Iptal','-') durum,
 *          decode(odemetipi,'P','Pesin','V','Vadeli','-') odemesekli,
 *          decode(odemetipi,'P',pesin_tut,'V',vadeli_tut,'-') toplamtutar,
 *          pesinat_tut,
 *          fatodemeno,
 *          taksitsayisi,
 *          decode(kmh_drm,1,'Talep Bulunamadi',2,'Basarili',9,'Basarisiz','-') kmh_drm,
 *          kmh_limit,
 *          plan_bld_tar,
 *          tarih, sube, hesno, ilktaksittar,
 *          hata_ack
 *   FROM okul_odeme_plan
 *   WHERE (pkurum = 0 OR fatkurumno = pkurum)
 *   AND (iogrencino IS NULL OR ogrencino = trim(iogrencino))
 *   AND (iTCKN IS NULL OR TCKN = trim(iTCKN))
 *   AND (iokulodemeplanno IS NULL OR okulodemeplanno = iokulodemeplanno)
 *   AND (wBastar IS NULL OR tarih>=wBastar)
 *   AND (wBittar IS NULL OR tarih<=wBittar)
 *   AND (pdrm = 0 OR ((pdrm=9 AND drm=pdrm) OR (pdrm=1 AND drm IN (1,2))))
 *   ORDER BY 1 DESC;
 *
 * CURSOR cur_kurum (pFatkurumno IN NUMBER) IS
 *   SELECT ref_fat_sorgu_tur
 *   FROM fat_kurum
 *   WHERE fatkurumno = pFatkurumno;
 */
@RestController
@RequestMapping("/api/reports")
public class WpRpCrOkulOdemeKontrolSController {

    private final OkulOdemePlanService okulOdemePlanService;
    private final KurumService kurumService;
    private final PlsqlFunctionsService plsqlFunctionsService;

    public WpRpCrOkulOdemeKontrolSController(OkulOdemePlanService okulOdemePlanService,
                                             KurumService kurumService,
                                             PlsqlFunctionsService plsqlFunctionsService) {
        this.okulOdemePlanService = okulOdemePlanService;
        this.kurumService = kurumService;
        this.plsqlFunctionsService = plsqlFunctionsService;
    }

    @PostMapping("/okul-odeme-kontrol")
    public List<ReportGridDTO> getOkulOdemeKontrol(@RequestBody WpRpCrOkulOdemeKontrolSRequestDTO request) {

        Integer pkurum = request.pkurum();
        String iogrencino = request.iogrencino();
        String iTCKN = request.iTCKN();
        String dbastar = request.dbastar();
        String dbittar = request.dbittar();
        Integer iokulodemeplanno = request.iokulodemeplanno();
        Integer pdrm = request.pdrm() != null ? request.pdrm() : 0; // DEFAULT 0

        // Local variables from procedure body
        LocalDate wBastar = null;
        LocalDate wBittar = null;
        Integer wTur = null;
        String wFAT_HATA_ACK = null;
        String wrenk = null;
        String wPesinatTahsilDrm = null;
        Integer wKurumCalismaTipi = null;
        String wPlanBildirilmeDurumu = null;
        String whesmusteriadi = null;

        // Validation Logic (Rule 3.2)
        // Note: In a real Spring Boot app, these might throw exceptions or return error DTOs.
        // Here we simulate the logic flow. If validation fails, we might return empty or specific error grids.
        // For this conversion, we assume valid input proceeds to data retrieval.

        // PLSQL: IF iokulodemeplanno IS null AND pkurum = 0 THEN ...
        if (iokulodemeplanno == null && pkurum != null && pkurum == 0) {
            // Error: Lütfen Kurum Bilgisi veya TEB Kayit No Bilgisini Doldurunuz.
            return List.of(); 
        }

        // PLSQL: ELSIF (dbastar IS NOT NULL AND F_TARIH_KONT(dbastar, 'DDMMRR') = 0 ) ...
        if (dbastar != null && plsqlFunctionsService.tarihKont(dbastar, "DDMMRR") == 0) {
             // Error: Lutfen Tarih Araligi Bilgisini Dogru Formatta Doldurunuz.
             return List.of();
        }
        if (dbittar != null && plsqlFunctionsService.tarihKont(dbittar, "DDMMRR") == 0) {
             // Error: Lutfen Tarih Araligi Bilgisini Dogru Formatta Doldurunuz.
             return List.of();
        }

        // PLSQL: ELSIF to_date(dbittar,'DDMMRR') < to_date(dbastar,'DDMMRR') THEN
        // Parsing dates for comparison. Assuming format DDMMRR (DDMMYY)
        LocalDate parsedDbastar = parseDate(dbastar);
        LocalDate parsedDbittar = parseDate(dbittar);

        if (parsedDbastar != null && parsedDbittar != null && parsedDbittar.isBefore(parsedDbastar)) {
            // Error: Baslangiç Tarihi Bitis Tarihinden Büyük Olamaz.
            return List.of();
        }

        // PLSQL: ELSIF iokulodemeplanno IS NOT NULL AND f_number_kont(iokulodemeplanno) = 0 THEN
        if (iokulodemeplanno != null && plsqlFunctionsService.numberKont(iokulodemeplanno) == 0) {
            // Error: Lutfen Teb Kayit No Bilgisini Dogru Formatta Doldurunuz.
            return List.of();
        }

        // Assign dates if valid
        wBastar = parsedDbastar;
        wBittar = parsedDbittar;

        // Rule 1.3: Call dummy services
        List<OkulOdemePlanDTO> okulOdemePlanlari = okulOdemePlanService.getOkulOdemePlanlari(
                pkurum, iogrencino, iTCKN, iokulodemeplanno, wBastar, wBittar, pdrm
        );

        // Build the main table
        ReportGridDTO mainTable = buildMainTable(okulOdemePlanlari);

        // The procedure also outputs a "Seçilen Kriterler" table via web_ortak.p_form_tablo_ac
        // This is often a summary/header table. We can include it as a separate grid if needed, 
        // but typically the main data grid is the primary return. 
        // Based on rule 1.4, we return List<ReportGridDTO>.

        return List.of(mainTable);
    }

    private LocalDate parseDate(String dateStr) {
        if (dateStr == null || dateStr.isEmpty()) return null;
        try {
            // Assuming DDMMRR format (e.g., 010124 for Jan 1, 2024)
            // Java LocalDate.parse with pattern ddMMyy
            return LocalDate.parse(dateStr, DateTimeFormatter.ofPattern("ddMMyy"));
        } catch (Exception e) {
            return null;
        }
    }

    private ReportGridDTO buildMainTable(List<OkulOdemePlanDTO> data) {
        // Headers from web_ortak.p_tablo_ac
        List<GridHeaderDTO> headers = List.of(
            new GridHeaderDTO(1, "TEB Kayit No", "Integer", true),
            new GridHeaderDTO(2, "Kurum", "String", true),
            new GridHeaderDTO(3, "Ögrenci No", "String", true),
            new GridHeaderDTO(4, "Borç No", "String", true),
            new GridHeaderDTO(5, "Borç Ack", "String", true),
            new GridHeaderDTO(6, "TCKN", "String", true),
            new GridHeaderDTO(7, "Ad Soyad", "String", true),
            new GridHeaderDTO(8, "Fakülte", "String", true),
            new GridHeaderDTO(9, "Bölüm", "String", true),
            new GridHeaderDTO(10, "Plan Olusturulma Tarihi", "Date", true),
            new GridHeaderDTO(11, "Plan Durumu", "String", true),
            new GridHeaderDTO(12, "Ödeme Sekli", "String", true),
            new GridHeaderDTO(13, "Toplam Tutar", "Number", true),
            new GridHeaderDTO(14, "Pesinat", "Number", true),
            new GridHeaderDTO(15, "Pesinat Tahsil Durumu", "String", true),
            new GridHeaderDTO(16, "Taksit Sayisi", "Integer", true),
            new GridHeaderDTO(17, "Taksit Baslangiç Tarihi", "Date", true),
            new GridHeaderDTO(18, "KMH Durumu", "String", true),
            new GridHeaderDTO(19, "KMH Tutari", "Number", true),
            new GridHeaderDTO(20, "Veli Sube", "Integer", true),
            new GridHeaderDTO(21, "Veli Hesap No", "Integer", true),
            new GridHeaderDTO(22, "Veli Ad Soyad", "String", true),
            new GridHeaderDTO(23, "Plan Bildirilme Durumu", "String", true),
            new GridHeaderDTO(24, "Ödeme Hata Açiklama", "String", true),
            new GridHeaderDTO(25, "Detay", "String", false) // Link column
        );

        List<GridRowDTO> rows = data.stream().map(r -> {
            // Logic for wPesinatTahsilDrm
            String wPesinatTahsilDrm = null;
            if (r.pesinatTut() != null && r.pesinatTut().compareTo(BigDecimal.ZERO) == 0) {
                wPesinatTahsilDrm = "-";
            } else {
                if (r.fatodemeno() == null) {
                    wPesinatTahsilDrm = "Tahsil edilmedi";
                } else {
                    wPesinatTahsilDrm = "Tahsil edildi";
                }
            }

            // Logic for wKurumCalismaTipi and wPlanBildirilmeDurumu
            Integer wKurumCalismaTipi = null;
            KurumCalismaTipiDTO kurumInfo = kurumService.getKurumCalismaTipi(r.fatkurumno());
            if (kurumInfo != null) {
                wKurumCalismaTipi = kurumInfo.refFatSorguTur();
            }

            String wPlanBildirilmeDurumu = null;
            if (wKurumCalismaTipi != null && wKurumCalismaTipi == 2) { // OFFLINE
                if (r.planBldTar() != null) {
                    wPlanBildirilmeDurumu = "Okula Bildirildi";
                } else {
                    wPlanBildirilmeDurumu = "Okula Bildirilmedi";
                }
            } else { // Online
                if (r.drm() != null && r.drm() == 2) {
                    wPlanBildirilmeDurumu = "Okula Bildirildi";
                } else {
                    wPlanBildirilmeDurumu = "Okula Bildirilmedi";
                }
            }

            // Logic for whesmusteriadi
            String whesmusteriadi = null;
            if (r.sube() != null && r.hesno() != null) {
                whesmusteriadi = plsqlFunctionsService.getHesapMusteriAdiGenel(r.hesno(), r.sube());
            }

            // Logic for wFAT_HATA_ACK
            String wFAT_HATA_ACK = null;
            if (r.hataAck() == null) {
                // Simulating the select from tb.fat_odeme
                // In a real scenario, this would be another service call
                wFAT_HATA_ACK = null; 
            } else {
                wFAT_HATA_ACK = r.hataAck();
            }

            // Build Cells
            List<GridCellDTO> cells = new ArrayList<>();
            cells.add(new GridCellDTO(1, r.okulodemeplanno()));
            cells.add(new GridCellDTO(2, r.fatkurumno() + " - " + plsqlFunctionsService.getKurumAdi(r.fatkurumno(), "A")));
            cells.add(new GridCellDTO(3, r.ogrencino()));
            cells.add(new GridCellDTO(4, r.borcno()));
            cells.add(new GridCellDTO(5, r.borcack()));
            cells.add(new GridCellDTO(6, r.tckn()));
            cells.add(new GridCellDTO(7, r.adsoyad()));
            cells.add(new GridCellDTO(8, r.fakulte()));
            cells.add(new GridCellDTO(9, r.bolum()));
            cells.add(new GridCellDTO(10, plsqlFunctionsService.formatDate(r.tarih())));
            cells.add(new GridCellDTO(11, r.durum()));
            cells.add(new GridCellDTO(12, r.odemesekli()));
            cells.add(new GridCellDTO(13, plsqlFunctionsService.tutarFormatla("TL", r.toplamtutar())));
            cells.add(new GridCellDTO(14, plsqlFunctionsService.tutarFormatla("TL", r.pesinatTut())));
            cells.add(new GridCellDTO(15, wPesinatTahsilDrm));
            cells.add(new GridCellDTO(16, r.taksitsayisi()));
            cells.add(new GridCellDTO(17, plsqlFunctionsService.formatDate(r.ilktaksittar())));
            cells.add(new GridCellDTO(18, r.kmhDrm()));
            cells.add(new GridCellDTO(19, plsqlFunctionsService.tutarFormatla("TL", r.kmhLimit())));
            cells.add(new GridCellDTO(20, r.sube()));
            cells.add(new GridCellDTO(21, r.hesno()));
            cells.add(new GridCellDTO(22, whesmusteriadi));
            cells.add(new GridCellDTO(23, wPlanBildirilmeDurumu));
            cells.add(new GridCellDTO(24, wFAT_HATA_ACK));

            // Link Cell
            String linkUrl = "/api/reports/okul-odeme-kontrol-detay?pokulodemeplanno=" + r.okulodemeplanno();
            LinkCellDTO linkCell = plsqlFunctionsService.fLink(linkUrl, "Detaylar için tiklayiniz.");
            cells.add(new GridCellDTO(25, linkCell));

            return new GridRowDTO(cells);
        }).collect(Collectors.toList());

        return new ReportGridDTO("Okul Tahsilatlari Gözlem", headers, rows);
    }
}

